315	    /**
316	     * Normalizes the submitted {@code address} on create to its canonical form (see
317	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
318	     * stored and returned, and the form every later address comparison (the required-field check,
319	     * household duplicate detection and the shared household id) is judged on. A null address is left
320	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
321	     * after normalization likewise reduces to the empty string and is rejected there.
322	     *
323	     * @param ownerFieldsDto the submitted owner fields
324	     */
325	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
326	        String address = ownerFieldsDto.getAddress();
327	        if (address == null) {
328	            return;
329	        }
330	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
331	    }
332	
333	    /**
334	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
335	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
336	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
337	     * {@code 400 Bad Request}.
338	     *
339	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
340	     *                       {@link #rejectBlankOwnerFields} having already run)
341	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
342	     */
343	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
344	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
345	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
346	        ownerFieldsDto.setTelephone(normalized);
347	    }
348	
349	    /**
350	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
351	     * untouched (email is optional). When present it is reduced to its canonical form (see
352	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
353	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
354	     *
355	     * @param ownerFieldsDto the submitted owner fields
356	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
357	     */
358	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
359	        String email = ownerFieldsDto.getEmail();
360	        if (email == null || email.isBlank()) {
361	            return;
362	        }
363	        String normalized = EmailNormalizer.normalize(email)
364	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
365	        ownerFieldsDto.setEmail(normalized);
366	    }
367	
368	    /**
369	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
370	     * duplicate detection is now expressed through the single derived {@code identityKey}
371	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
372	     * which replaces the previously separate telephone, email and household checks. Two owners denote
373	     * the same person when their identities collide on the telephone - the identity's distinguishing
374	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
375	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
376	     * same household with different telephones have different identities and are both allowed; an email
377	     * or a household on its own no longer makes a duplicate.
378	     *
379	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
380	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
381	     * @param householdId    the household id derived for the owner being created (see
382	     *                       {@link HouseholdNormalizer#toHouseholdId})
383	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
384	     */
385	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
386	        String identityKey = OwnerIdentity.identityKey(
387	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
388	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
389	        boolean inUse = this.clinicService.findAllOwners().stream()
390	            .map(Owner::getTelephone)
391	            .filter(Objects::nonNull)
392	            .map(TelephoneNormalizer::toComparisonKey)
393	            .anyMatch(telephoneKey::equals);
394	        if (inUse) {
395	            throw new DuplicateOwnerIdentityException(identityKey);
396	        }
397	    }
398	
399	    /**
400	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
401	     * both match the submitted values, compared case-insensitively. The count reflects only owners
402	     * already persisted at the time of the create, so the owner being created is never included.
403	     *
404	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
405	     *                  having already run)
406	     * @param lastName  the submitted last name (non-blank here)
407	     * @return the number of existing owners sharing the same first and last name
408	     */
409	    private int countNamesakes(String firstName, String lastName) {
410	        return (int) this.clinicService.findAllOwners().stream()
411	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
412	                && lastName.equalsIgnoreCase(owner.getLastName()))
413	            .count();
414	    }
415	
416	    /**
417	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
418	     * whose stored {@code householdId} equals the value derived for the owner being created. The
419	     * count reflects only owners already persisted at the time of the create, so the owner being
420	     * created is never included; callers add one to obtain the household size after this create.
421	     *
422	     * @param householdId the household identifier derived for the owner being created (see
423	     *                    {@link HouseholdNormalizer#toHouseholdId})
424	     * @return the number of existing owners already sharing that household
425	     */
426	    private int countHouseholdMembers(String householdId) {
427	        if (householdId == null) {
428	            return 0;
429	        }
430	        return (int) this.clinicService.findAllOwners().stream()
431	            .map(Owner::getHouseholdId)
432	            .filter(householdId::equals)
433	            .count();
434	    }
435	
436	    /**
437	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
438	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
439	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
440	     *
441	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
442	     *             run)
443	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
444	     */
445	    private void rejectCityAtCapacity(String city) {
446	        long ownersInCity = this.clinicService.findAllOwners().stream()
447	            .map(Owner::getCity)
448	            .filter(Objects::nonNull)
449	            .filter(city::equalsIgnoreCase)
450	            .count();
451	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
452	            throw new OwnerCityAtCapacityException(city);
453	        }
454	    }
455	
456	    /**
457	     * Resolves the effective registration date for a create, rolled onto a business day. The
458	     * supplied date is used when present, otherwise the server's current date; either way the result
459	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
460	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
461	     * stored {@code registrationDate}, the membership number's year segment and the daily
462	     * create-limit's per-day count - is judged on this adjusted date.
463	     *
464	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
465	     *                                 default to the server's current date
466	     * @return the effective registration date, guaranteed to fall on a business day
467	     */
468	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
469	        LocalDate registrationDate =
470	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
471	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
472	    }
473	
474	    /**
475	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
476	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
477	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
478	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
479	     * Too Many Requests}.
480	     *
481	     * @param registrationDate   the create's effective registration date, already rolled onto a
482	     *                           business day by {@link #effectiveRegistrationDate}
483	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
484	     *                           {@code registrationDate} equals {@code registrationDate}
485	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
486	     *                                              owner registrations
487	     */
488	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
489	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
490	            throw new OwnerDailyRegistrationLimitException(registrationDate);
491	        }
492	    }
493	
494	    /**
495	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
496	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
497	     * bulk-signup warning are judged on.
498	     *
499	     * @param registrationDate the create's effective registration date, already rolled onto a business
500	     *                         day by {@link #effectiveRegistrationDate}
501	     * @return the number of existing owners registered on that day
502	     */
503	    private long countRegisteredOn(LocalDate registrationDate) {
504	        return this.clinicService.findAllOwners().stream()
505	            .map(Owner::getRegistrationDate)
506	            .filter(registrationDate::equals)
507	            .count();
508	    }
509	}
