193	    /**
194	     * Handles {@link DuplicateOwnerException} and its subtypes, each thrown when an owner create
195	     * request would duplicate an existing owner under some uniqueness rule (telephone, household,
196	     * ...). Returns a 409 Conflict carrying the exception's own client-facing detail and the names of
197	     * the offending request fields in the {@code errors} array, so a new uniqueness rule needs only a
198	     * new subtype rather than another handler here.
199	     *
200	     * @param e The {@link DuplicateOwnerException} to be handled
201	     * @param request {@link HttpServletRequest} object referring to the current request.
202	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
203	     */
204	    @ExceptionHandler(DuplicateOwnerException.class)
205	    @ResponseBody
206	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerException(DuplicateOwnerException e, HttpServletRequest request) {
207	        HttpStatus status = HttpStatus.CONFLICT;
208	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getDetail());
209	        detail.setProperty("errors", e.getErrorFields());
210	        logger.debug("Duplicate owner at {} {}: {}",
211	            request.getMethod(),
212	            request.getRequestURI(),
213	            e.getMessage());
214	        return ResponseEntity.status(status).body(detail);
215	    }
216	
217	    /**
218	     * Handles {@link OwnerCityAtCapacityException}, thrown when an owner create request targets a city
219	     * that has already reached its maximum number of owners. Returns a 409 Conflict carrying the
220	     * exception's client-facing detail and {@code city} in the {@code errors} array.
221	     *
222	     * @param e The {@link OwnerCityAtCapacityException} to be handled
223	     * @param request {@link HttpServletRequest} object referring to the current request.
224	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
225	     */
226	    @ExceptionHandler(OwnerCityAtCapacityException.class)
227	    @ResponseBody
228	    public ResponseEntity<ProblemDetail> handleOwnerCityAtCapacityException(OwnerCityAtCapacityException e, HttpServletRequest request) {
229	        HttpStatus status = HttpStatus.CONFLICT;
230	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getDetail());
231	        detail.setProperty("errors", e.getErrorFields());
232	        logger.debug("Owner city at capacity at {} {}: {}",
233	            request.getMethod(),
234	            request.getRequestURI(),
235	            e.getMessage());
236	        return ResponseEntity.status(status).body(detail);
237	    }
238	
239	    /**
240	     * Handles {@link OwnerDailyRegistrationLimitException}, thrown when an owner create request would
241	     * exceed the number of owners that may be registered in a single day. Returns a 429 Too Many
242	     * Requests carrying the exception's client-facing detail and {@code registrationDate} in the
243	     * {@code errors} array.
244	     *
