246	     * @param request {@link HttpServletRequest} object referring to the current request.
247	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
248	     */
249	    @ExceptionHandler(OwnerDailyRegistrationLimitException.class)
250	    @ResponseBody
251	    public ResponseEntity<ProblemDetail> handleOwnerDailyRegistrationLimitException(OwnerDailyRegistrationLimitException e, HttpServletRequest request) {
252	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
253	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getDetail());
254	        detail.setProperty("errors", e.getErrorFields());
255	        logger.debug("Owner daily registration limit reached at {} {}: {}",
256	            request.getMethod(),
257	            request.getRequestURI(),
258	            e.getMessage());
259	        return ResponseEntity.status(status).body(detail);
260	    }
